import{z as s,x as i,o as e,c as l,q as t,j as n,D as a,d as r,s as B,S as o}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"数据版本化","description":"","frontmatter":{"title":"数据版本化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/de-data-versioning.md","filePath":"quant/de-data-versioning.md","lastUpdated":1791413859000}'),d={name:"quant/de-data-versioning.md"};function p(h,E,u,D,C,m){const A=i("Mermaid");return e(),l("div",null,[E[2]||(E[2]=t('<h1 id="数据版本化" tabindex="-1">数据版本化 <a class="header-anchor" href="#数据版本化" aria-label="Permalink to &quot;数据版本化&quot;">​</a></h1><div class="epigraph"><p>代码有版本控制而数据没有，实验就不可复现；更糟的是，没人能证明它不可复现。</p><footer>—— 据 Ljungqvist, Malloy and Marston, Rewriting History, Journal of Finance, 2009；Lakehouse 时间旅行（Delta Lake、Iceberg）公开规范整理</footer></div><p><a href="/quant/de-corporate-action-deep">上一课</a>把调整因子做成带生效区间的版本序列，改写不触历史；那只是四张表里的一个特例。本课把同一原则推广到全平台：供应商会重述，清洗规则会修订，复权口径会升级——每一次改写都把「上周的回测」变成无法重建的幽灵。缺口是让数据像代码一样有版本：任何历史结果都能钉回到当时那份字节上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>不可复现有三个来源，全都不报错。<span class="marginnote">常见误区：初学者容易以为「代码进了 git，实验就能复现」。实际上同一份代码、同一行 SQL，跑在上周和今天的数据上就是两个实验——供应商改过值、清洗规则升级过，数据自己会变。不可复现的源头通常不在代码仓库，而在没被版本化的数据与规则。</span><strong>就地更新</strong>：供应商修正写到旧行上，值变好了，历史没了；<a href="/quant/point-in-time">点时基本面</a>记录过 I/B/E/S 推荐历史被整体改写，没有 vintage 快照的团队连「数据动过」都无法发现。<strong>选择性重拉</strong>：新数据补了 2020 年以后的行情，更早的还是旧管道产物，一张表里混着两代口径，差异只在个别字段与边缘日期<span class="marginnote">直觉类比：选择性重拉像一本书前半是旧版、后半是新版——单看每页都「像数据」，可两代的排版规则不同，凡是跨前后半的统计都说不清。混代表最难排查，因为它不整段报错，只在接缝处渗出。</span>——像数据、像泄漏、像 alpha，无法区分。<strong>规则漂移</strong>：清洗规则改了，同一批原始字节产出不同序列，而结果表没有任何字段记录用了哪条规则。三者共同的下游症状是：两次运行同一份代码得到不同数字，且回答不了「哪一次对」。</p>',5)),(e(),n(o,null,{default:a(()=>[B(A,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20SRC%5B%22%E4%B8%89%E4%B8%AA%E9%9D%99%E9%BB%98%E6%9D%A5%E6%BA%90%22%5D%0A%20%20%20%20U1%5B%22%E5%B0%B1%E5%9C%B0%E6%9B%B4%E6%96%B0%3A%20%E6%97%A7%E8%A1%8C%E8%A2%AB%E8%A6%86%E7%9B%96%22%5D%20--%3E%20SY%5B%22%E6%95%B0%E6%8D%AE%E5%8A%A8%E8%BF%87%E5%8D%B4%E6%97%A0%E4%BA%BA%E7%9F%A5%E6%99%93%22%5D%0A%20%20%20%20U2%5B%22%E9%80%89%E6%8B%A9%E6%80%A7%E9%87%8D%E6%8B%89%3A%20%E4%B8%80%E8%A1%A8%E4%B8%A4%E4%BB%A3%E5%8F%A3%E5%BE%84%22%5D%20--%3E%20SY2%5B%22%E6%8E%A5%E7%BC%9D%E5%A4%84%E5%83%8F%20alpha%20%E5%8F%88%E5%83%8F%E6%B3%84%E6%BC%8F%22%5D%0A%20%20%20%20U3%5B%22%E8%A7%84%E5%88%99%E6%BC%82%E7%A7%BB%3A%20%E8%A7%84%E5%88%99%E6%94%B9%E4%BA%86%E6%B2%A1%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20SY3%5B%22%E5%90%8C%E7%A0%81%E4%B8%A4%E6%AC%A1%E8%BF%90%E8%A1%8C%E4%B8%A4%E4%B8%AA%E6%95%B0%22%5D%0A%20%20end%0A%20%20SY%20--%3E%20QS%5B%22%E5%85%B1%E5%90%8C%E7%97%87%E7%8A%B6%3A%20%E6%97%A0%E6%B3%95%E5%9B%9E%E7%AD%94%E5%93%AA%E4%B8%80%E6%AC%A1%E5%AF%B9%22%5D%0A%20%20SY2%20--%3E%20QS%0A%20%20SY3%20--%3E%20QS%0A%20%20FIX%5B%22%E8%A7%A3%E6%B3%95%3A%20%E4%B8%8D%E5%8F%AF%E5%8F%98%E5%AD%98%E5%82%A8%20%2B%20%E5%86%85%E5%AE%B9%E5%93%88%E5%B8%8C%20%2B%20%E8%A7%84%E5%88%99%E5%85%A5%E7%89%88%E6%9C%AC%22%5D%20-.%20%22%E9%92%89%E5%9B%9E%E5%AD%97%E8%8A%82%22%20.-%3E%20QS%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h3 id="版本化的对象与粒度" tabindex="-1">版本化的对象与粒度 <a class="header-anchor" href="#版本化的对象与粒度" aria-label="Permalink to &quot;版本化的对象与粒度&quot;">​</a></h3><p>粒度三级，按需取用。快照级：整库某日的只读视图，最贵但最无歧义，用于归档与审计。数据集级：数据集标识加版本号加日期分区，是实验引用的默认单位。行级：每行带 published_at 与修订链，是<a href="/quant/alt-panel-construction">面板构造</a>与 as-of 查询的底层。三者不是竞争关系：行级是摄取层的事，数据集级是实验层的事，快照级是合规层的事。</p><p><span class="marginnote">内容寻址是版本号不出错的关键：版本标识用内容的哈希而不是人起的日期名。两张「v2024-06-01」的表若哈希不同，说明重算过——人名会撞车，哈希不会。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地四条。<strong>一，存储不可变</strong>：已写入的分区只读，修正写新分区；这与<a href="/quant/de-tsdb-selection">时序数据库的选型</a>的 append-only 不变量是同一件事在治理层的表达。<span class="marginnote">数字实例：不可变分区的存储成本大约是覆盖式的两倍——1 TB 的行情库，一年重算 12 次约多写 12 TB。对照一次「回测结果无法重建、整个项目作废」的事故，这笔钱通常是最便宜的保险。</span><strong>二，三要素哈希</strong>：每个实验钉住定义哈希、数据版本哈希、清洗规则哈希的三元组，与<a href="/quant/fml-feature-store-deep">特征存储的深入</a>的钉法一致——特征、数据、规则在同一个哈希空间里对齐。<strong>三，schema 演化走前向兼容</strong>：加列可以，改语义必须升数据集大版本，旧版本继续可读。<strong>四，重算即发布</strong>：因为供应商修正或规则升级而重算历史时，发布新版本并写变更日志，而不是覆盖；下游显式迁移，才允许引用切换。</p>',5)),(e(),n(o,null,{default:a(()=>[B(A,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E4%BE%9B%E5%BA%94%E5%95%86%E5%8E%9F%E5%A7%8B%E5%AD%97%E8%8A%82%EF%BC%9A%E4%B8%8D%E5%8F%AF%E5%8F%98%22%5D%20--%3E%20ING%5B%22%E6%91%84%E5%8F%96%EF%BC%9A%E8%A1%8C%E7%BA%A7%20published_at%20%E4%B8%8E%E4%BF%AE%E8%AE%A2%E9%93%BE%22%5D%0A%20%20ING%20--%3E%20DS%5B%22%E6%95%B0%E6%8D%AE%E9%9B%86%E7%89%88%E6%9C%AC%EF%BC%9A%E5%86%85%E5%AE%B9%E5%93%88%E5%B8%8C%22%5D%0A%20%20RULE%5B%22%E6%B8%85%E6%B4%97%E8%A7%84%E5%88%99%E7%89%88%E6%9C%AC%22%5D%20--%3E%20DS%0A%20%20DS%20--%3E%20EXP%5B%22%E5%AE%9E%E9%AA%8C%EF%BC%9A%E5%AE%9A%E4%B9%89%E5%93%88%E5%B8%8C%20%2B%20%E6%95%B0%E6%8D%AE%E5%93%88%E5%B8%8C%20%2B%20%E8%A7%84%E5%88%99%E5%93%88%E5%B8%8C%22%5D%0A%20%20DS%20--%3E%20NEWV%5B%22%E4%BF%AE%E6%AD%A3%EF%BC%9A%E5%8F%91%E5%B8%83%E6%96%B0%E7%89%88%E6%9C%AC%EF%BC%8C%E5%86%99%E5%8F%98%E6%9B%B4%E6%97%A5%E5%BF%97%22%5D%0A%20%20NEWV%20--%3E%20DS%0A%20%20EXP%20--%3E%20REPRO%5B%22%E5%8E%86%E5%8F%B2%E7%BB%93%E6%9E%9C%E5%8F%AF%E7%B2%BE%E7%A1%AE%E9%87%8D%E5%BB%BA%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>版本化的收益不是「以防万一」，而是把两类原本不可判定的争论变成可判定。第一类是复现争议：结果表钉了三元哈希后，「上周那个模型」可以逐字节重建，差异必然来自代码、数据或规则三者之一的显式变更——排查从考古变成查日志。第二类是修正偏好的争议：供应商重述与自建修正同时存在时，两个版本并列保留，因子在两代口径上的差值本身成为一个可测对象；把它测出来，就知道研究结论有多少建立在最新修正上。机制上，不可变存储是这三件事的共同前提：只有旧版本永不动，新版本才有资格被称为「新」。这也是<a href="/quant/research-postmortem">复盘</a>口径在数据层的落点——死因要落在判据上，而判据引用的每个数字都必须能溯源到一次具体的发布。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>版本化有成本：存储翻倍、目录治理、迁移纪律，小团队常以「先跑通再说」跳过，等第一轮无法复现的研究事故再补，代价更大。行级修订链不是万能替代品：有些供应商根本不提供历史快照，此时只能统一滞后近似并显式记录，见<a href="/quant/data-acquisition-audit">数据获取与审计</a>的降级口径。版本也不自动带来正确：两个版本可能都错，对账靠外部证据，监控由后续质量课接管。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>不可复现三源：就地更新、选择性重拉、规则漂移，全都静默。</li><li>粒度三级：行级管摄取、数据集级管实验、快照级管归档。</li><li>实验钉三要素哈希：定义、数据版本、清洗规则，与特征存储同构。</li><li>修正走发布不覆盖，旧版本永不可变，迁移显式化。</li><li>出处：Ljungqvist, Malloy and Marston, <em>Rewriting History</em>, <em>JF</em>, 2009；Delta Lake 与 Iceberg 公开规范；站内<a href="/quant/fml-feature-store-deep">特征存储的深入</a>的三元组口径。</li></ul>',6))])}const f=s(d,[["render",p]]);export{c as __pageData,f as default};
